import { Composition } from 'remotion';
import timing from '../timing.json';
import { AbsoluteFill } from 'remotion';
import { HeirloomDemo, DemoProps } from './HeirloomDemo';
import { Captions } from './components/Overlays';
import { loadFonts } from './fonts';

/** Captions alone on transparency: rendered as ProRes 4444 and overlaid on the silent master by ffmpeg. */
const CaptionsLayer: React.FC = () => {
  loadFonts();
  return (
    <AbsoluteFill>
      <Captions />
    </AbsoluteFill>
  );
};

export const RemotionRoot: React.FC = () => (
  <>
    <Composition
      id="HeirloomDemo"
      component={HeirloomDemo}
      durationInFrames={timing.totalFrames}
      fps={timing.fps}
      width={timing.width}
      height={timing.height}
      defaultProps={{ captions: false, audio: false }}
      calculateMetadata={({ props }) => {
        if (!props.only) return {};
        const s = timing.scenes.find((x) => x.id === props.only)!;
        return { durationInFrames: s.frames };
      }}
    />
    <Composition id="CaptionsLayer" component={CaptionsLayer} durationInFrames={timing.totalFrames} fps={timing.fps} width={timing.width} height={timing.height} />
  </>
);
// Builds video/timing.json (scene starts/lengths in frames, caption chunks, SFX cues) and video/captions.srt.
// With VO files in public/audio/vo/S01.mp3…S10.mp3 each scene becomes head 0.4 s + VO + tail 0.6 s
// (S10: + 4 s end-card hold). Without them, the brief's target lengths are used.
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { SCENES, FPS, HEAD, TAIL, END_HOLD } from './scenes.mjs';

const root = join(import.meta.dirname, '..');
const MAX = 42;

const probe = (file) =>
  Number(execFileSync('ffprobe', ['-v', 'error', '-show_entries', 'format=duration', '-of', 'csv=p=0', file], { encoding: 'utf8' }).trim());

/** Two balanced lines of ≤42 chars, preferring a break after punctuation. */
function twoLines(block) {
  if (block.length <= MAX) return block;
  const words = block.split(' ');
  let best = null;
  for (let i = 1; i < words.length; i++) {
    const l1 = words.slice(0, i).join(' ');
    const l2 = words.slice(i).join(' ');
    if (l1.length > MAX || l2.length > MAX) continue;
    const score = Math.abs(l1.length - l2.length) - (/[,:;…]$/.test(l1) ? 12 : 0) - (/^—/.test(l2) ? 12 : 0);
    if (!best || score < best.score) best = { score, text: `${l1}\n${l2}` };
  }
  return best ? best.text : block;
}

/** Split VO into captions: one or two lines of ≤42 chars, never across a sentence end. */
export function chunk(text) {
  const sentences = text.replace(/\s+/g, ' ').trim().match(/[^.?!…]+[.?!…]+["”']?\s*|[^.?!…]+$/g).map((x) => x.trim());
  const out = [];
  for (const sentence of sentences) {
    const clauses = sentence.split(/(?<=[,:;…])\s+|\s+(?=— )/).filter(Boolean);
    let cur = '';
    for (const clause of clauses) {
      const joined = cur ? `${cur} ${clause}` : clause;
      if (joined.length <= 2 * MAX - 6 && twoLines(joined).split('\n').every((l) => l.length <= MAX)) cur = joined;
      else {
        if (cur) out.push(cur);
        cur = clause;
      }
    }
    if (cur) out.push(cur);
  }
  return out.map(twoLines);
}

const cues = JSON.parse(readFileSync(join(root, 'sfx-cues.json'), 'utf8'));

let start = 0;
const scenes = [];
const captions = [];
let anyVo = false;
for (const s of SCENES) {
  const voFile = join(root, 'public/audio/vo', `${s.id}.mp3`);
  const hasVo = existsSync(voFile);
  anyVo ||= hasVo;
  const vo = hasVo ? probe(voFile) : null;
  const tail = s.id === 'S10' ? END_HOLD : TAIL;
  const seconds = vo ? HEAD + vo + tail : s.target;
  const frames = Math.round(seconds * FPS);
  // the window where words are spoken
  const speechFrom = start + Math.round(HEAD * FPS);
  const speechTo = start + frames - Math.round(tail * FPS);
  const chunks = chunk(s.vo);
  // weight each chunk by characters, plus a beat for sentence ends
  const weights = chunks.map((c) => c.length + (/[.?!…]$/.test(c) ? 8 : /[,—:]$/.test(c) ? 4 : 0));
  const total = weights.reduce((a, b) => a + b, 0);
  let t = speechFrom;
  chunks.forEach((text, i) => {
    const len = ((speechTo - speechFrom) * weights[i]) / total;
    captions.push({ scene: s.id, text, from: Math.round(t), to: Math.round(t + len) - 2 });
    t += len;
  });
  const scale = frames / Math.round(s.target * FPS);
  scenes.push({ id: s.id, title: s.title, start, frames, target: Math.round(s.target * FPS), scale: Number(scale.toFixed(4)), vo: s.vo, voFile: hasVo ? `audio/vo/${s.id}.mp3` : null, voSeconds: vo });
  start += frames;
}

const sfx = cues.map((c) => {
  const sc = scenes.find((x) => x.id === c.scene);
  return { ...c, frame: sc.start + Math.round(c.at * FPS * sc.scale) };
});

const timing = { fps: FPS, width: 1920, height: 1080, totalFrames: start, voPresent: anyVo, head: HEAD, tail: TAIL, endHold: END_HOLD, scenes, captions, sfx };
writeFileSync(join(root, 'timing.json'), JSON.stringify(timing, null, 1) + '\n');

const tc = (f) => {
  const ms = Math.round((f / FPS) * 1000);
  const p = (n, w = 2) => String(n).padStart(w, '0');
  return `${p(Math.floor(ms / 3600000))}:${p(Math.floor(ms / 60000) % 60)}:${p(Math.floor(ms / 1000) % 60)},${p(ms % 1000, 3)}`;
};
const srt = captions.map((c, i) => `${i + 1}\n${tc(c.from)} --> ${tc(c.to)}\n${c.text}\n`).join('\n');
writeFileSync(join(root, 'captions.srt'), srt);

console.log(`timing.json: ${scenes.length} scenes, ${start} frames (${(start / FPS).toFixed(2)} s), ${captions.length} captions, VO ${anyVo ? 'present' : 'absent (target lengths)'}`);
for (const s of scenes) console.log(`  ${s.id} ${(s.start / FPS).toFixed(2).padStart(7)}s  ${(s.frames / FPS).toFixed(2)}s`);
const long = captions.filter((c) => c.text.split('\n').some((l) => l.length > MAX));
if (long.length) console.log('WARNING over-long captions:', long);
import React from 'react';
import { useCurrentFrame } from 'remotion';
import { C, EASE_IN_OUT, FONT, VERDICT } from '../theme';
import { io, springStamp, springUI } from '../lib/anim';
import { Hallmark, GuillocheRing } from './Engraving';
import { BrassUnderline, Counter } from './Kinetic';
import timing from '../../timing.json';

/** Lower third: brass rule grows, then a mono kicker and a sans line slide up. */
export const LowerThird: React.FC<{ at: number; out: number; title: React.ReactNode; kicker?: string; x?: number; y?: number; width?: number }> = ({
  at,
  out,
  title,
  kicker,
  x = 96,
  y = 742,
  width = 980,
}) => {
  const frame = useCurrentFrame();
  if (frame < at - 1 || frame > out + 30) return null;
  const t = io(frame, at + 8, 30);
  const o = 1 - io(frame, out, 22, EASE_IN_OUT);
  return (
    <div style={{ position: 'absolute', left: x, top: y, opacity: o }}>
      <div
        style={{
          position: 'absolute',
          left: -28,
          top: -22,
          width: width + 56,
          height: 150,
          borderRadius: 18,
          background: 'linear-gradient(90deg, rgba(8,9,10,0.92), rgba(8,9,10,0.78) 70%, rgba(8,9,10,0))',
          opacity: io(frame, at, 24),
        }}
      />
      <div style={{ position: 'relative' }}>
        <BrassUnderline at={at} width={Math.min(width, 380)} dur={34} />
        {kicker && (
          <div style={{ marginTop: 14, fontFamily: FONT.mono, fontSize: 22, letterSpacing: '0.16em', color: C.brass, opacity: t, transform: `translateY(${(1 - t) * 14}px)` }}>{kicker}</div>
        )}
        <div style={{ marginTop: 8, fontFamily: FONT.sans, fontSize: 42, fontWeight: 500, color: C.bone, opacity: io(frame, at + 14, 30), transform: `translateY(${(1 - io(frame, at + 14, 30)) * 18}px)`, whiteSpace: 'nowrap' }}>
          {title}
        </div>
      </div>
    </div>
  );
};

/** Naive pipeline vs Heirloom on the known-answer backtest. */
export const BacktestSplit: React.FC<{ at: number; heirloomDelay?: number; v1: { false_not_affected: number; cases: number }; v2: { false_not_affected: number; cases: number } }> = ({ at, v1, v2, heirloomDelay = 26 }) => {
  const frame = useCurrentFrame();
  const split = io(frame, at, 50, EASE_IN_OUT);
  const side = (label: string, sub: string, n: number, col: string, delay: number, dir: number) => {
    // label and caption arrive with the split; the number lands on its own VO beat
    const s = springUI(frame, at + 6 + (dir > 0 ? 14 : 0));
    const num = springUI(frame, at + delay);
    return (
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 18, opacity: s, transform: `translateX(${(1 - s) * 60 * dir}px)` }}>
        <div style={{ fontFamily: FONT.mono, fontSize: 24, letterSpacing: '0.18em', color: C.muted }}>{label}</div>
        <div style={{ position: 'relative', fontFamily: FONT.serif, fontSize: 300, lineHeight: 0.9, height: 270, color: col, textShadow: `0 0 60px ${col}55` }}>
          <span style={{ position: 'absolute', left: '50%', transform: 'translateX(-50%)', color: C.line, textShadow: 'none', opacity: 1 - num }}>·</span>
          <span style={{ display: 'inline-block', opacity: num, transform: `scale(${1.25 - 0.25 * num})` }}>
            <Counter from={0} to={n} at={at + delay} dur={30} />
          </span>
        </div>
        <div style={{ fontFamily: FONT.sans, fontSize: 34, color: C.bone, textAlign: 'center', lineHeight: 1.3 }}>{sub}</div>
      </div>
    );
  };
  return (
    <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'stretch', padding: '140px 120px 200px' }}>
      {side('NAIVE PIPELINE', `false “not affected” · ${v1.cases} known-answer cases`, v1.false_not_affected, VERDICT.AFFECTED.color, 6, -1)}
      <div style={{ width: 2, margin: '0 60px', background: `linear-gradient(180deg, transparent, ${C.brass}, transparent)`, transform: `scaleY(${split})` }} />
      {side('HEIRLOOM', `false “not affected” · ${v2.cases} known-answer cases`, v2.false_not_affected, VERDICT.FIX_READY.color, heirloomDelay, 1)}
    </div>
  );
};

/** "PRECEDENT SEALED · P001": a wax-and-brass seal that presses in. */
export const PrecedentSeal: React.FC<{ at: number; id: string; answer: string; size?: number }> = ({ at, id, answer, size = 420 }) => {
  const frame = useCurrentFrame();
  const s = springStamp(frame, at);
  const shock = io(frame, at + 4, 40);
  if (frame < at) return null;
  return (
    <div style={{ position: 'relative', width: size, height: size, transform: `scale(${1.8 - 0.8 * s}) rotate(${(1 - s) * -12}deg)`, opacity: Math.min(1, s * 2) }}>
      <div style={{ position: 'absolute', inset: -40, borderRadius: '50%', border: `2px solid ${C.brassHi}`, opacity: (1 - shock) * 0.7, transform: `scale(${0.8 + shock * 0.6})` }} />
      <div
        style={{
          position: 'absolute',
          inset: 0,
          borderRadius: '50%',
          background: `radial-gradient(circle at 38% 32%, #3a2f1b, #1a150c 60%, #0d0b07)`,
          boxShadow: `0 0 0 3px ${C.brass}, 0 30px 90px rgba(0,0,0,0.8), 0 0 80px rgba(230,203,142,0.25), inset 0 0 40px rgba(0,0,0,0.7)`,
        }}
      />
      <div style={{ position: 'absolute', inset: 14 }}>
        <GuillocheRing size={size - 28} at={-999} copies={10} lobes={30} amp={2.4} r={44} strokeWidth={0.3} opacity={0.75} rotate={frame * 0.05} />
      </div>
      <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 6 }}>
        <div style={{ fontFamily: FONT.mono, fontSize: 24, letterSpacing: '0.3em', color: C.brass }}>PRECEDENT</div>
        <div style={{ fontFamily: FONT.serif, fontSize: 132, color: C.brassHi, lineHeight: 1 }}>{id}</div>
        <div style={{ fontFamily: FONT.mono, fontSize: 24, letterSpacing: '0.3em', color: C.brass }}>SEALED</div>
      </div>
      <div style={{ position: 'absolute', left: -200, right: -200, top: size + 56, textAlign: 'center', fontFamily: FONT.mono, fontSize: 30, color: C.bone, opacity: io(frame, at + 24, 30), transform: `scale(${1 / (1.8 - 0.8 * s)})` }}>
        /heirloom answer <span style={{ color: C.brassHi }}>{answer}</span>
      </div>
    </div>
  );
};

/** The closing card. */
export const EndCard: React.FC<{ at: number; site: string; repo: string; credit: string }> = ({ at, site, repo, credit }) => {
  const frame = useCurrentFrame();
  return (
    <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center' }}>
      <Hallmark size={220} at={at} />
      <div style={{ marginTop: 34, fontFamily: FONT.serif, fontSize: 150, color: C.bone, lineHeight: 1, opacity: io(frame, at + 40, 40), transform: `translateY(${(1 - io(frame, at + 40, 40)) * 24}px)` }}>Heirloom</div>
      <div style={{ marginTop: 14, fontFamily: FONT.serif, fontSize: 54, color: C.muted, opacity: io(frame, at + 56, 40) }}>
        Old software, <span style={{ fontStyle: 'italic', color: C.brassHi }}>kept honest.</span>
      </div>
      <BrassUnderline at={at + 70} width={420} style={{ marginTop: 40 }} />
      <div style={{ marginTop: 36, display: 'flex', gap: 56, fontFamily: FONT.mono, fontSize: 30, color: C.bone, opacity: io(frame, at + 86, 36) }}>
        <span>{site}</span>
        <span style={{ color: C.line }}>│</span>
        <span>{repo}</span>
      </div>
      <div style={{ marginTop: 28, fontFamily: FONT.sans, fontSize: 28, color: C.muted, opacity: io(frame, at + 104, 36) }}>{credit}</div>
    </div>
  );
};

/** Burned-in captions from timing.json: Geist 34 px, bone on a 70% ink pill, bottom centre. */
export const Captions: React.FC = () => {
  const frame = useCurrentFrame();
  const c = timing.captions.find((x) => frame >= x.from && frame <= x.to);
  if (!c) return null;
  const t = Math.min(io(frame, c.from, 8), 1 - io(frame, c.to - 6, 6));
  return (
    <div style={{ position: 'absolute', left: 0, right: 0, bottom: 64, display: 'flex', justifyContent: 'center', pointerEvents: 'none' }}>
      <div
        style={{
          fontFamily: FONT.sans,
          fontSize: 34,
          lineHeight: 1.3,
          color: C.bone,
          background: 'rgba(8,9,10,0.7)',
          padding: '10px 28px 12px',
          borderRadius: c.text.includes('\n') ? 26 : 999,
          whiteSpace: 'pre-line',
          opacity: t,
          maxWidth: 1400,
          textAlign: 'center',
        }}
      >
        {c.text}
      </div>
    </div>
  );
};

