import React from 'react';
import { Freeze, getStaticFiles, Img, OffthreadVideo, Sequence, staticFile, useCurrentFrame, useVideoConfig } from 'remotion';
import captures from '../data/captures.json';
import { C, FONT } from '../theme';
import { io } from '../lib/anim';
import { GuillocheRing, Vignette } from './Engraving';

const CAPS = captures as Record<string, { seconds: number; file: string; source?: string }>;

const has = (name: string) => getStaticFiles().some((f) => f.name === name);
/** "BR01" also matches V-CAP's descriptive names such as "BR01-balance-wheel-skeleton". */
const resolve = (id: string) => (CAPS[id] ? id : Object.keys(CAPS).find((k) => k.startsWith(`${id}-`)) ?? id);
export const captureFile = (id: string) => (CAPS[resolve(id)] ? CAPS[resolve(id)].file : `captures/${id}.mp4`);
export const hasCapture = (id: string) => has(captureFile(id));
const capInfo = (id: string) => CAPS[resolve(id)];
/** Seconds of a delivered clip (0 when missing). */
export const captureSeconds = (id: string) => (hasCapture(id) ? capInfo(id)?.seconds ?? 0 : 0);

/** Labelled stand-in until V-CAP's real clip lands in public/captures/. */
const Placeholder: React.FC<{ id: string; label: string }> = ({ id, label }) => {
  const frame = useCurrentFrame();
  return (
    <div
      style={{
        position: 'absolute',
        inset: 0,
        background: `repeating-linear-gradient(135deg, ${C.raised} 0 22px, #0d0f10 22px 44px)`,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        flexDirection: 'column',
        gap: 22,
      }}
    >
      <div style={{ position: 'absolute', opacity: 0.25, transform: `rotate(${frame * 0.1}deg)` }}>
        <GuillocheRing size={620} at={-999} strokeWidth={0.12} />
      </div>
      <div style={{ fontFamily: FONT.mono, fontSize: 30, color: C.brassHi, letterSpacing: '0.2em' }}>CAPTURE {id}</div>
      <div style={{ fontFamily: FONT.sans, fontSize: 34, color: C.bone, maxWidth: 1100, textAlign: 'center' }}>{label}</div>
      <div style={{ fontFamily: FONT.mono, fontSize: 22, color: C.muted }}>placeholder · replaced by ~/video-out/captures/{id}.mp4</div>
    </div>
  );
};

/**
 * A real screen capture. `window` composites it over ink as a rounded window with a brass hairline;
 * `full` fills the frame. Always: a slow 3% push-in and a soft vignette. Holds the last frame if the slot outlasts the clip.
 */
export const CaptureClip: React.FC<{
  id: string;
  label: string;
  url?: string;
  mode?: 'window' | 'full';
  startFrom?: number; // seconds into the clip
  rate?: number;
  push?: number;
  origin?: string;
  scale?: number; // window size relative to the frame
  enter?: boolean;
  vignette?: number;
  baseZoom?: number; // crop into the clip (e.g. to keep a site's modal out of frame)
}> = ({ id, label, url, mode = 'window', startFrom = 0, rate = 1, push = 0.03, origin = '50% 50%', scale = 0.86, enter = true, baseZoom = 1, vignette = 0.35 }) => {
  const frame = useCurrentFrame();
  const { durationInFrames, fps } = useVideoConfig();
  const ok = hasCapture(id);
  const p = frame / Math.max(1, durationInFrames);
  const zoom = baseZoom * (1 + push * p);
  const info = capInfo(id);
  const clipFrames = info ? Math.floor(((info.seconds - startFrom) * fps) / rate) - 1 : Infinity;
  const src = ok ? staticFile(captureFile(id)) : '';
  const media = ok ? (
    <>
      <Sequence durationInFrames={Number.isFinite(clipFrames) ? Math.max(1, clipFrames) : undefined} layout="none">
        <OffthreadVideo src={src} startFrom={Math.round(startFrom * fps)} playbackRate={rate} muted style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
      </Sequence>
      {Number.isFinite(clipFrames) && frame >= clipFrames && (
        <Freeze frame={Math.max(0, clipFrames - 1)}>
          <OffthreadVideo src={src} startFrom={Math.round(startFrom * fps)} playbackRate={rate} muted style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover' }} />
        </Freeze>
      )}
    </>
  ) : (
    <Placeholder id={id} label={label} />
  );
  const inner = (
    <div style={{ position: 'absolute', inset: 0, transform: `scale(${zoom})`, transformOrigin: origin }}>
      {media}
    </div>
  );
  if (mode === 'full') {
    return (
      <div style={{ position: 'absolute', inset: 0, overflow: 'hidden', background: C.ink }}>
        {inner}
        <Vignette strength={0.55} />
      </div>
    );
  }
  const e = enter ? io(frame, 0, 40) : 1;
  const w = 1920 * scale;
  const h = 1080 * scale;
  return (
    <div style={{ position: 'absolute', inset: 0 }}>
      <div
        style={{
          position: 'absolute',
          left: (1920 - w) / 2,
          top: (1080 - h) / 2 + 12,
          width: w,
          height: h,
          borderRadius: 20,
          padding: 1.5,
          background: `linear-gradient(135deg, ${C.brassHi}, ${C.brassLo} 35%, ${C.brass} 65%, ${C.brassLo})`,
          boxShadow: '0 50px 140px rgba(0,0,0,0.75), 0 0 80px rgba(200,168,106,0.10)',
          opacity: e,
          transform: `translateY(${(1 - e) * 30}px) scale(${0.985 + 0.015 * e})`,
        }}
      >
        <div style={{ position: 'relative', width: '100%', height: '100%', borderRadius: 18.5, overflow: 'hidden', background: C.ink }}>
          <div style={{ position: 'absolute', left: 0, top: 0, width: 1920, height: 1080, transform: `scale(${scale})`, transformOrigin: '0 0' }}>{inner}</div>
          {vignette > 0 && <Vignette strength={vignette} />}
        </div>
      </div>
      {url && (
        <div
          style={{
            position: 'absolute',
            left: (1920 - w) / 2 + 4,
            top: (1080 - h) / 2 - 30,
            fontFamily: FONT.mono,
            fontSize: 22,
            color: C.muted,
            opacity: e,
            letterSpacing: '0.02em',
          }}
        >
          <span style={{ color: C.brass }}>●</span> {url}
        </div>
      )}
    </div>
  );
};

/** A still photo from the site's own photo set (Unsplash), with a Ken Burns drift: the b-roll stand-in. */
export const Photo: React.FC<{ src: string; push?: number; dim?: number; origin?: string }> = ({ src, push = 0.06, dim = 0.45, origin = '50% 50%' }) => {
  const frame = useCurrentFrame();
  const { durationInFrames } = useVideoConfig();
  const z = 1 + push * (frame / durationInFrames);
  return (
    <div style={{ position: 'absolute', inset: 0, overflow: 'hidden' }}>
      <Img src={staticFile(src)} style={{ width: '100%', height: '100%', objectFit: 'cover', transform: `scale(${z})`, transformOrigin: origin, filter: 'saturate(0.8) contrast(1.05)' }} />
      <div style={{ position: 'absolute', inset: 0, background: `rgba(8,9,10,${dim})` }} />
      <Vignette strength={0.85} />
    </div>
  );
};

export { has as hasStatic };
import React from 'react';
import { AbsoluteFill, Sequence } from 'remotion';
import { C, FONT } from '../theme';

export type SceneProps = { scale: number; frames: number };

/** A mono kicker in the top-left safe corner: the record we're looking at. */
export const Kicker: React.FC<{ children: React.ReactNode; opacity?: number; style?: React.CSSProperties }> = ({ children, opacity = 1, style }) => (
  <div style={{ position: 'absolute', left: 96, top: 64, fontFamily: FONT.mono, fontSize: 22, letterSpacing: '0.16em', color: C.muted, opacity, ...style }}>{children}</div>
);

/** Sequence shorthand: [from, to) in frames. */
export const Seq: React.FC<{ from: number; to: number; children: React.ReactNode; name?: string }> = ({ from, to, children, name }) => (
  <Sequence from={from} durationInFrames={Math.max(1, to - from)} name={name}>
    <AbsoluteFill>{children}</AbsoluteFill>
  </Sequence>
);
import React from 'react';
import { AbsoluteFill, useCurrentFrame } from 'remotion';
import { C, EASE_IN_OUT, FONT, VERDICT } from '../theme';
import { beats, io, lerp } from '../lib/anim';
import { DatePlates } from '../components/Plates';
import { Terminal, TermLine } from '../components/Terminal';
import { VerdictChip } from '../components/Verdict';
import { KineticTitle } from '../components/Kinetic';
import { Ground } from '../components/Engraving';
import { daysBetween, FINDING, shortDate, terminal, UBUNTU } from '../data';
import { SceneProps } from './common';

export const S03: React.FC<SceneProps> = ({ scale }) => {
  const frame = useCurrentFrame();
  const b = beats(scale);
  const up = io(frame, b(6.0), 56, EASE_IN_OUT);
  const toClaim = io(frame, b(14.2), 40, EASE_IN_OUT);
  const runs = terminal.probe.runs;
  const red = VERDICT.AFFECTED.color;
  const lines: TermLine[] = [];
  runs.forEach((r, i) => {
    const t0 = b(7.2) + i * b(1.6);
    lines.push({ text: `── ${r.file}   ${r.exit}`, at: t0, color: C.muted, size: 22 });
    lines.push({ text: r.test, at: t0 + 10, color: C.bone, size: 22 });
    lines.push({ text: r.assertion, at: t0 + 26, color: red, weight: 500, size: 22 });
    lines.push({ text: r.result, at: t0 + 38, color: red, size: 22 });
  });
  const fix = FINDING.fix_commit.slice(0, 8);
  return (
    <AbsoluteFill>
      <Ground ringOpacity={0.05} glow={1 + up} />
      <AbsoluteFill style={{ opacity: 1 - toClaim, filter: toClaim > 0 ? `blur(${toClaim * 10}px)` : undefined }}>
        <div style={{ position: 'absolute', left: 0, right: 0, top: lerp(380, 40, up), transform: `scale(${lerp(1, 0.8, up)})`, transformOrigin: '50% 0' }}>
          <DatePlates
            at={b(0.3)}
            lockAt={b(3.0)}
            days={daysBetween(FINDING.distro_date, FINDING.advisory_date)}
            left={{ date: shortDate(FINDING.distro_date), text: <>Ubuntu ships its <span style={{ fontFamily: FONT.mono, color: C.brassHi, whiteSpace: 'nowrap' }}>{FINDING.amends}</span> backport</> }}
            right={{ date: shortDate(FINDING.advisory_date), text: <>Django: <span style={{ fontFamily: FONT.mono, color: C.brassHi, whiteSpace: 'nowrap' }}>{FINDING.cve}</span> amends that fix</> }}
          />
        </div>
        {frame >= b(6.2) && (
          <div style={{ position: 'absolute', left: 140, top: 300 }}>
            <Terminal
              at={b(6.3)}
              width={1640}
              height={630}
              title={`${UBUNTU.name} noble · python-django ${UBUNTU.version} · probe hl_cve_2026_87890 · runs ×3`}
              lines={lines}
              fontSize={22}
            />
            <div style={{ position: 'absolute', right: 48, bottom: 40 }}>
              <VerdictChip chip="AFFECTED" at={b(12.9)} size={34} />
            </div>
          </div>
        )}
      </AbsoluteFill>
      {frame >= b(14.2) && (
        <AbsoluteFill style={{ alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ width: 1500, textAlign: 'center' }}>
            <div style={{ display: 'flex', justifyContent: 'center', marginBottom: 40, opacity: io(frame, b(14.4), 30) }}>
              <VerdictChip chip="AFFECTED" at={b(14.4)} size={26} />
            </div>
            <KineticTitle text={FINDING.claim} at={b(14.6)} size={66} align="center" lineHeight={1.18} stagger={2.2} />
            <div style={{ marginTop: 44, fontFamily: FONT.mono, fontSize: 24, color: C.muted, opacity: io(frame, b(16.4), 36) }}>
              hand-written probe, calibrated on Django&apos;s fix commits {fix}^ / {fix}
            </div>
          </div>
        </AbsoluteFill>
      )}
    </AbsoluteFill>
  );
};
import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { C, EASE_IN_OUT } from '../theme';
import { GuillocheRing } from './Engraving';

export const IRIS_FRAMES = 42;
const DIAG = Math.hypot(960, 540) + 40;

/** Brass-ring iris: the incoming scene opens through a circle whose rim is a brass guilloché ring. */
export const IrisTransition: React.FC<{ children: React.ReactNode; frames?: number }> = ({ children, frames = IRIS_FRAMES }) => {
  const frame = useCurrentFrame();
  if (frame >= frames) return <AbsoluteFill>{children}</AbsoluteFill>;
  const t = interpolate(frame, [0, frames], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: EASE_IN_OUT });
  const r = t * DIAG;
  const rimOpacity = interpolate(t, [0, 0.1, 0.8, 1], [0, 1, 1, 0]);
  return (
    <AbsoluteFill>
      <AbsoluteFill style={{ clipPath: `circle(${r}px at 50% 50%)` }}>{children}</AbsoluteFill>
      <AbsoluteFill style={{ alignItems: 'center', justifyContent: 'center', pointerEvents: 'none' }}>
        <svg width={1920} height={1080} style={{ position: 'absolute', inset: 0 }}>
          <circle cx={960} cy={540} r={r} fill="none" stroke={C.brassHi} strokeWidth={3} opacity={rimOpacity} />
          <circle cx={960} cy={540} r={r + 14} fill="none" stroke={C.brass} strokeWidth={1} opacity={rimOpacity * 0.6} />
        </svg>
        <div style={{ position: 'absolute', opacity: rimOpacity * 0.7, transform: `rotate(${t * 90}deg)` }}>
          <GuillocheRing size={(r + 30) * 2 * 1.25} at={-999} copies={8} lobes={48} amp={1.4} r={40} strokeWidth={0.12} />
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};
import { interpolate, spring } from 'remotion';
import { EASE_IN_OUT, EASE_OUT, FPS, SPRING_STAMP, SPRING_UI } from '../theme';

const clamp = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;

/** 0→1 over [at, at+dur] with the house ease-out. */
export const io = (frame: number, at: number, dur = 36, ease = EASE_OUT) =>
  interpolate(frame, [at, at + dur], [0, 1], { ...clamp, easing: ease });
export const inOut = (frame: number, at: number, dur = 48) => io(frame, at, dur, EASE_IN_OUT);
export const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

export const springUI = (frame: number, at: number) => spring({ frame: frame - at, fps: FPS, config: SPRING_UI });
export const springStamp = (frame: number, at: number) => spring({ frame: frame - at, fps: FPS, config: SPRING_STAMP });

/** Visible between in and out with fades at both ends: 0→1→0. */
export const window = (frame: number, at: number, out: number, fadeIn = 24, fadeOut = 18) =>
  Math.min(io(frame, at, fadeIn), 1 - io(frame, out - fadeOut, fadeOut, EASE_IN_OUT));

/** Seconds → frames, scaled to the scene's retimed length. */
export const beats = (scale: number) => (sec: number) => Math.round(sec * FPS * scale);
export const sec = (s: number) => Math.round(s * FPS);

